@Test
public void testProduceConsume() throws Exception {
    factory = new JmsConnectionFactory(getAmqpURI(getAmqpConnectionURIOptions()));
    factory.setForceAsyncAcks(true);
    factory.setForceAsyncSend(false);
    factory.setForceSyncSend(false);
    final AtomicLong sharedSendCount = new AtomicLong(NUM_SENDS);
    final AtomicLong sharedReceiveCount = new AtomicLong(NUM_SENDS);
    Thread.sleep(2000);
    long start = System.currentTimeMillis();
    ExecutorService executorService = Executors.newFixedThreadPool(parallelConsumer + parallelProducer);
    for (int i = 0; i < parallelConsumer; i++) {
        executorService.execute(new Runnable() {

            @Override
            public void run() {
                try {
                    consumeMessages(sharedReceiveCount);
                } catch (Throwable e) {
                    exceptions.add(e);
                }
            }
        });
    }
    for (int i = 0; i < parallelProducer; i++) {
        executorService.execute(new Runnable() {

            @Override
            public void run() {
                try {
                    publishMessages(sharedSendCount);
                } catch (Throwable e) {
                    exceptions.add(e);
                }
            }
        });
    }
    executorService.shutdown();
    executorService.awaitTermination(30, TimeUnit.MINUTES);
    assertTrue("Producers done in time", executorService.isTerminated());
    assertTrue("No exceptions: " + exceptions, exceptions.isEmpty());
    double duration = System.currentTimeMillis() - start;
    LOG.info("Duration:            " + duration + "ms");
    LOG.info("Rate:                " + (NUM_SENDS * 1000 / duration) + "m/s");
}

@Ignore("Used for profiling broker memory usage.")
@Test
public void testBrowserLeak() throws JMSException, InterruptedException {
    connection = createConnection();
    Session session = connection.createSession(true, Session.SESSION_TRANSACTED);
    Queue queue = session.createQueue(getDestinationName());
    session.close();
    for (int i = 1; i <= NUM_ITERATIONS; ++i) {
        // When recreating session, memory leak does occurs on the client but memory leak still occurs on the server
        session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        QueueBrowser browser = session.createBrowser(queue, "JMSXGroupSeq=0");
        int j = 1;
        Enumeration<?> enums = browser.getEnumeration();
        if (!enums.hasMoreElements()) {
            LOG.debug("No messages in {}", queue.getQueueName());
        } else {
            Message message = (Message) enums.nextElement();
            if (message != null) {
                LOG.debug("Received {} message : {} from {}", new Object[] { j++, message, queue.getQueueName() });
            }
        }
        LOG.debug("close browser for {}", queue.getQueueName());
        try {
            browser.close();
        } catch (JMSException e) {
            LOG.error("Error on browser close: {}", e);
        }
        browser = null;
        LOG.debug("close session for {}", queue.getQueueName());
        try {
            session.close();
        } catch (JMSException e) {
            LOG.error("Error on session close: {}", e);
        }
        session = null;
    }
    LOG.info("Task complete, capture heap dump now");
    TimeUnit.MINUTES.sleep(5);
}

