    final ArrayList<byte[]> tags = new ArrayList<>(tagLoop);
    for (int i = 0; i < Short.MAX_VALUE * 16; ++i) {
        // Checkout all the tags the pool will create
        for (int j = 0; j < tagLoop; ++j) {
