@Test
public void testResize() throws IOException {
    int initSize = 64;
    DataByteArrayOutputStream out = new DataByteArrayOutputStream();
    fillOut(out, initSize);
    // Should resized here
    out.writeBoolean(true);
    fillOut(out, initSize);
    // Should resized here
    out.writeByte(1);
    fillOut(out, initSize);
    // Should resized here
    out.writeBytes("test");
    fillOut(out, initSize);
    // Should resized here
    out.writeChar('C');
    fillOut(out, initSize);
    // Should resized here
    out.writeChars("test");
    fillOut(out, initSize);
    // Should resized here
    out.writeDouble(3.1416);
    fillOut(out, initSize);
    // Should resized here
    out.writeFloat((float) 3.1416);
    fillOut(out, initSize);
    // Should resized here
    out.writeInt(12345);
    fillOut(out, initSize);
    // Should resized here
    out.writeLong(12345);
    fillOut(out, initSize);
    // Should resized here
    out.writeShort(1234);
    fillOut(out, initSize);
    // Should resized here
    out.writeUTF("test");
    fillOut(out, initSize);
    // Should resized here
    out.write(1234);
    fillOut(out, initSize);
    // Should resized here
    out.write(new byte[10], 5, 5);
    fillOut(out, initSize);
    // Should resized here
    out.write(new byte[10]);
}

