    LOG.info("result of invoke: " + result);
    assertTrue("invoked", result.contains("Q2"));
    result = executeQuery("-QQueue=Q2 --view EnqueueCount");
    assertTrue("enqueueCount", result.contains("EnqueueCount = 1"));
}

