            return 0 == server.getCurrentTransportCount().get();
        }
    }, TimeUnit.SECONDS.toMillis(15), TimeUnit.MILLISECONDS.toMillis(500)));
    assertTrue("no exceptions", exceptions.isEmpty());
}

