@Test
public void testFailureOnSelectorThreadPoolExhaustion() throws Exception {
    final ConnectionFactory cf = createConnectionFactory();
    final CountDownLatch startupLatch = new CountDownLatch(1);
    final List<Exception> exceptions = Collections.synchronizedList(new LinkedList<Exception>());
    for (int i = 0; i < maxConnections; i++) {
        executor.submit(new Runnable() {

            @Override
            public void run() {
                ActiveMQConnection conn = null;
                try {
                    startupLatch.await();
                    conn = (ActiveMQConnection) cf.createConnection();
                    conn.start();
                    connections.add(conn);
                } catch (Exception e) {
                    exceptions.add(e);
                    JmsUtils.closeConnection(conn);
                }
            }
        });
    }
    // No connections at first
    assertEquals(0, connector.getConnections().size());
    // Release the latch to set up connections in parallel
    startupLatch.countDown();
    final TransportConnector connector = this.connector;
    // Expect the max connections is created
    assertTrue("Expected some exceptions", Wait.waitFor(new Wait.Condition() {

        @Override
        public boolean isSatisified() throws Exception {
            return !exceptions.isEmpty();
        }
    }));
    assertTrue("Expected some connections, provided not all errored out", Wait.waitFor(new Wait.Condition() {

        @Override
        public boolean isSatisified() throws Exception {
            LOG.info("Exceptions size: " + exceptions.size() + ", connections size: " + connector.getConnections().size());
            return exceptions.size() == maxConnections || connector.getConnections().size() > 0;
        }
    }));
    assertTrue("Expected: connections or exceptions match attempts: " + maxConnections, Wait.waitFor(new Wait.Condition() {

        @Override
        public boolean isSatisified() throws Exception {
            LOG.info("Exceptions size: " + exceptions.size() + ", connections size: " + connector.getConnections().size());
            return connector.getConnections().size() + exceptions.size() == maxConnections;
        }
    }));
}

@Test(timeout = 120000)
public void test() throws Exception {
    connection = createConnection();
    connection.start();
    final int MSG_COUNT = 100;
    final Session session = connection.createSession(false, Session.CLIENT_ACKNOWLEDGE);
    final Queue queue = session.createQueue(name.getMethodName());
    MessageProducer producer = session.createProducer(queue);
    producer.setDeliveryMode(DeliveryMode.NON_PERSISTENT);
    final QueueViewMBean queueView = getProxyToQueue(name.getMethodName());
    byte[] payload = new byte[65535];
    Arrays.fill(payload, (byte) 255);
    final CountDownLatch done = new CountDownLatch(1);
    final AtomicInteger counter = new AtomicInteger();
    Thread purge = new Thread(new Runnable() {

        @Override
        public void run() {
            try {
                while (!done.await(5, TimeUnit.SECONDS)) {
                    if (queueView.getBlockedSends() > 0 && queueView.getQueueSize() > 0) {
                        long queueSize = queueView.getQueueSize();
                        LOG.info("Queue send blocked at {} messages", queueSize);
                        MessageConsumer consumer = session.createConsumer(queue);
                        for (int i = 0; i < queueSize; i++) {
                            Message message = consumer.receive(60000);
                            if (message != null) {
                                counter.incrementAndGet();
                                message.acknowledge();
                            } else {
                                LOG.warn("Got null message when none as expected.");
                            }
                        }
                        consumer.close();
                    }
                }
            } catch (Exception ex) {
            }
        }
    });
    purge.start();
    for (int i = 0; i < MSG_COUNT; i++) {
        BytesMessage message = session.createBytesMessage();
        message.writeBytes(payload);
        producer.send(message);
        LOG.info("sent message: {}", i);
    }
    done.countDown();
    purge.join(60000);
    if (purge.isAlive()) {
        fail("Consumer thread should have read initial batch and completed.");
    }
    //wait for processed acked messages
    assertTrue(Wait.waitFor(new Condition() {

        @Override
        public boolean isSatisified() throws Exception {
            return queueView.getDequeueCount() == counter.get();
        }
    }));
    long remainingQueued = queueView.getQueueSize();
    LOG.info("Remaining messages to consume: {}", remainingQueued);
    assertEquals(remainingQueued, MSG_COUNT - counter.get());
    MessageConsumer consumer = session.createConsumer(queue);
    for (int i = counter.get(); i < MSG_COUNT; i++) {
        Message message = consumer.receive(5000);
        assertNotNull("Should not get null message", consumer);
        counter.incrementAndGet();
        message.acknowledge();
        LOG.info("Read message: {}", i);
    }
    assertEquals("Should consume all messages", MSG_COUNT, counter.get());
}

