@Test
public void testQueueMemoryUsage() throws Exception {
    final ArrayList<ThreadSlot> producerThreads = new ArrayList<>();
    final ArrayList<ThreadSlot> consumerThreads = new ArrayList<>();
    for (int i = 0; i < 4; i++) producerThreads.add(runInThread(new UnsafeRunnable() {

        @Override
        public void run() throws Exception {
            producer(connectionUri, "queueA");
        }
    }));
    for (int i = 0; i < 4; i++) consumerThreads.add(runInThread(new UnsafeRunnable() {

        @Override
        public void run() throws Exception {
            consumer(connectionUri, "queueA", 2500);
        }
    }));
    // kill and restart random threads
    for (int count = 0; count < 10; count++) {
        Thread.sleep(5000);
        final int i = (int) (Math.random() * consumerThreads.size());
        final ThreadSlot slot = consumerThreads.get(i);
        slot.thread.interrupt();
        consumerThreads.remove(i);
        consumerThreads.add(runInThread(slot.runnable));
        Queue queue = (Queue) brokerService.getDestination(new ActiveMQQueue("queueA"));
        LOG.info("cursorMemoryUsage: " + queue.getMessages().getSystemUsage().getMemoryUsage().getUsage());
        LOG.info("messagesStat: " + queue.getDestinationStatistics().getMessages().getCount());
    }
    // verify usage
    Queue queue = (Queue) brokerService.getDestination(new ActiveMQQueue("queueA"));
    LOG.info("cursorMemoryUsage: " + queue.getMessages().getSystemUsage().getMemoryUsage().getUsage());
    LOG.info("messagesStat: " + queue.getDestinationStatistics().getMessages().getCount());
    // drain the queue
    for (ThreadSlot threadSlot : producerThreads) {
        threadSlot.thread.interrupt();
        threadSlot.thread.join(4000);
    }
    for (ThreadSlot threadSlot : consumerThreads) {
        threadSlot.thread.interrupt();
        threadSlot.thread.join(4000);
    }
    consumer(connectionUri, "queueA", 2500, true);
    LOG.info("After drain, cursorMemoryUsage: " + queue.getMessages().getSystemUsage().getMemoryUsage().getUsage());
    LOG.info("messagesStat: " + queue.getDestinationStatistics().getMessages().getCount());
    assertEquals("Queue memory usage to 0", 0, queue.getMessages().getSystemUsage().getMemoryUsage().getUsage());
}

@Test
public void testViewIsStale() throws Exception {
    final int MSG_COUNT = 10;
    ActiveMQConnectionFactory cf = new ActiveMQConnectionFactory(broker.getVmConnectorURI());
    Connection connection = cf.createConnection();
    Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    Queue queue = session.createQueue("Test-Queue");
    Queue dlq = session.createQueue("ActiveMQ.DLQ");
    MessageProducer producer = session.createProducer(queue);
    // Ensure there is a DLQ in existence to start.
    session.createProducer(dlq);
    for (int i = 0; i < MSG_COUNT; ++i) {
        producer.send(session.createMessage(), DeliveryMode.PERSISTENT, Message.DEFAULT_PRIORITY, 1000);
    }
    final QueueViewMBean queueView = getProxyToQueue(dlq.getQueueName());
    assertTrue("Message should be DLQ'd", Wait.waitFor(new Wait.Condition() {

        @Override
        public boolean isSatisified() throws Exception {
            return queueView.getQueueSize() == MSG_COUNT;
        }
    }));
    LOG.info("DLQ has captured all expired messages");
    Deque<String> browsed = new LinkedList<String>();
    CompositeData[] elements = queueView.browse();
    assertEquals(MSG_COUNT, elements.length);
    for (CompositeData element : elements) {
        String messageID = (String) element.get("JMSMessageID");
        LOG.debug("MessageID: {}", messageID);
        browsed.add(messageID);
    }
    String removedMsgId = browsed.removeFirst();
    assertTrue(queueView.removeMessage(removedMsgId));
    assertEquals(MSG_COUNT - 1, queueView.getQueueSize());
    elements = queueView.browse();
    assertEquals(MSG_COUNT - 1, elements.length);
    for (CompositeData element : elements) {
        String messageID = (String) element.get("JMSMessageID");
        LOG.debug("MessageID: {}", messageID);
        assertFalse(messageID.equals(removedMsgId));
    }
}

