    for (int i = 0; i < numMessages; i++) {
        message.setIntProperty("C", i);
        Xid xid = createXid();
        xaResource.start(xid, XAResource.TMNOFLAGS);
        producer.send(virtualTopic, message);
        xaResource.end(xid, XAResource.TMSUCCESS);
        xaResource.commit(xid, true);
