        for (ConsumerHolder consumerHolder : consumerHolders) {
            Message m = consumerHolder.consumer.receive(4000);
            if (m != null && i == 50) {
                LOG.info("@ 50 Got: " + m.getIntProperty("C"));
            }
            if (consumerHolder.session.getTransacted()) {
                consumerHolder.session.commit();
            }
        }
    }
    // verify consumption
    for (final String consumerId : consumerIds) {
        assertTrue(Wait.waitFor(new Wait.Condition() {

            @Override
            public boolean isSatisified() throws Exception {
                Destination destination = broker.getDestination(new ActiveMQQueue("Consumer." + consumerId + ".VirtualTopic.A"));
                return 0 == destination.getMessageStore().getMessageCount();
            }
        }));
    }
}

@Test
public void testTopicWildcardAndPerDestinationFilteredAdapter() throws Exception {
    //create one topic and queue and send messages
    sendMessages(false);
    sendMessages(true);
    //the adapters will persist the data, topic will be by wildcard filtered adapter
    //and queue will be by per destionation adapter
    //stop broker and restart, the bug is that on restart wildcard filtered adapter adds one KahaDBPersistenceAdapter
    // when calling MultiKahaDBPersistenceAdapter.setFilteredPersistenceAdapters
    //and on the call to doStart of MultiKahaDBPersistenceAdapter it uses per destination filtered adapter to add
    //another KahaDBPersistenceAdapter and fails on jmx bean registration
    // the fix is to make sure to check the persistent adapter already exists or not when we do per destination
    // filtered adapter processing and only add if one does not exists already
    var multiKaha = (MultiKahaDBPersistenceAdapter) broker.getPersistenceAdapter();
    // Verify 2 adapters created and not 3
    assertEquals(2, multiKaha.getAdapters().size());
    Set<File> dirs = multiKaha.getAdapters().stream().map(adapter -> adapter.getDirectory()).collect(Collectors.toSet());
    broker.stop();
    broker.waitUntilStopped();
    //restart should succeed with fix
    prepareBrokerWithMultiStore(false);
    broker.start();
    broker.waitUntilStarted();
    // Verify 2 adapters created and not 3 and same dirs
    multiKaha = (MultiKahaDBPersistenceAdapter) broker.getPersistenceAdapter();
    assertEquals(2, multiKaha.getAdapters().size());
    assertEquals(dirs, multiKaha.getAdapters().stream().map(adapter -> adapter.getDirectory()).collect(Collectors.toSet()));
}

/**
 * Tests for AMQ-3965
 * Creates connection into broker using optimzeAcknowledge and prefetch=100
 * Creates producer and consumer. Producer sends 45 msgs that will expire
 * at consumer (but before being dispatched to app code).
 * Producer then sends 60 msgs without expiry.
 *
 * Consumer receives msgs using a MessageListener and increments a counter.
 * Main thread sleeps for 5 seconds and checks the counter value.
 * If counter != 60 msgs (the number of msgs that should get dispatched
 * to consumer) the test fails.
 */
@Test
public void testOptimizedAckWithExpiredMsgs() throws Exception {
    ActiveMQConnectionFactory connectionFactory = new ActiveMQConnectionFactory(connectionUri + "?jms.optimizeAcknowledge=true&jms.prefetchPolicy.all=100");
    // Create JMS resources
    Connection connection = connectionFactory.createConnection();
    Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    Destination destination = session.createQueue("TEST.FOO");
    // ***** Consumer code *****
    MessageConsumer consumer = session.createConsumer(destination);
    final MyMessageListener listener = new MyMessageListener();
    connection.setExceptionListener((ExceptionListener) listener);
    // ***** Producer Code *****
    MessageProducer producer = session.createProducer(destination);
    producer.setDeliveryMode(DeliveryMode.NON_PERSISTENT);
    String text = "Hello world! From: " + Thread.currentThread().getName() + " : " + this.hashCode();
    TextMessage message;
    // Produce msgs that will expire quickly
    for (int i = 0; i < 45; i++) {
        message = session.createTextMessage(text);
        producer.send(message, 1, 1, 100);
        LOG.trace("Sent message: " + message.getJMSMessageID() + " with expiry 10 msec");
    }
    // Produce msgs that don't expire
    for (int i = 0; i < 60; i++) {
        message = session.createTextMessage(text);
        producer.send(message, 1, 1, 60000);
        // producer.send(message);
        LOG.trace("Sent message: " + message.getJMSMessageID() + " with expiry 30 sec");
    }
    consumer.setMessageListener(listener);
    // let the batch of 45 expire.
    sleep(1000);
    connection.start();
    assertTrue("Should receive all expected messages, counter at " + listener.getCounter(), Wait.waitFor(new Wait.Condition() {

        @Override
        public boolean isSatisified() throws Exception {
            return listener.getCounter() == 60;
        }
    }));
    LOG.info("Received all expected messages with counter at: " + listener.getCounter());
    // Cleanup
    producer.close();
    consumer.close();
    session.close();
    connection.close();
}

