    for (int i = 0; i < 2; i++) {
        LOG.info("Started the test iteration: " + i + " using queueName = " + queueName);
        queueName = QUEUE_NAME + i;
        final CountDownLatch latch = new CountDownLatch(11);
        pool.execute(new Runnable() {

            @Override
