                }
            });
        }
        LOG.info("Waiting on the send / receive latch");
        latch.await(5, TimeUnit.MINUTES);
        LOG.info("Resumed");
        destroyQueue();
        TimeUnit.SECONDS.sleep(2);
    }
    LOG.info("MemoryUsage before awaiting temp store cleanup = " + broker.getAdminView().getMemoryPercentUsage());
