@Test
public void testTransactedStoreUsageSuspendResume() throws Exception {
    ConsumerThread thread = new ConsumerThread();
    thread.start();
    ExecutorService sendExecutor = Executors.newSingleThreadExecutor();
    sendExecutor.execute(new Runnable() {

        @Override
        public void run() {
            try {
                sendMessages();
            } catch (Exception ignored) {
            }
        }
    });
    sendExecutor.shutdown();
    sendExecutor.awaitTermination(10, TimeUnit.MINUTES);
    boolean allMessagesReceived = messagesReceivedCountDown.await(10, TimeUnit.MINUTES);
    if (!allMessagesReceived) {
        LOG.info("Giving up - not all received on time...");
        LOG.info("System Mem Usage: " + broker.getSystemUsage().getMemoryUsage());
        LOG.info("System Store Usage: " + broker.getSystemUsage().getStoreUsage());
        LOG.info("Producer sent: " + messagesSentCountDown.getCount());
        LOG.info("Consumer remaining to receive: " + messagesReceivedCountDown.getCount());
        TestSupport.dumpAllThreads("StuckConsumer!");
    }
    assertTrue("Got all messages: " + messagesReceivedCountDown, allMessagesReceived);
    // give consumers a chance to exit gracefully
    TimeUnit.SECONDS.sleep(5);
}

@Test
public void bytesMessageCorruption() throws Exception {
    BrokerService brokerService = new BrokerService();
    brokerService.setBrokerName("embedded");
    brokerService.setPersistent(false);
    brokerService.start();
    ActiveMQConnectionFactory connectionFactory = new ActiveMQConnectionFactory("vm://embedded");
    connectionFactory.setUseCompression(true);
    Connection connection = connectionFactory.createConnection();
    connection.start();
    for (int i = 0; i < 10; i++) {
        Session mySession = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
        mySession.createConsumer(mySession.createTopic("foo.bar")).setMessageListener(new MessageListener() {

            @Override
            public void onMessage(Message message) {
                try {
                    Assert.assertEquals(1l, ((ActiveMQBytesMessage) message).getBodyLength());
                    Assert.assertEquals("a".getBytes()[0], ((ActiveMQBytesMessage) message).readByte());
                } catch (JMSException | Error e) {
                    assertionError = new AssertionError("Exception in thread", e);
                }
            }
        });
    }
    Session producerSession = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    MessageProducer messageProducer = producerSession.createProducer(producerSession.createTopic("foo.bar"));
    for (int i = 0; i < 1000; i++) {
        BytesMessage bytesMessage = producerSession.createBytesMessage();
        bytesMessage.writeBytes("a".getBytes());
        messageProducer.send(bytesMessage);
        if (assertionError != null) {
            throw assertionError;
        }
    }
    assertNull(assertionError);
}

@Test(timeout = 10000)
public void testBytesConversion() throws JMSException, IOException {
    ActiveMQMapMessage msg = new ActiveMQMapMessage();
    msg.setBoolean("boolean", true);
    msg.setByte("byte", (byte) 1);
    msg.setBytes("bytes", new byte[1]);
    msg.setChar("char", 'a');
    msg.setDouble("double", 1.5);
    msg.setFloat("float", 1.5f);
    msg.setInt("int", 1);
    msg.setLong("long", 1);
    msg.setObject("object", "stringObj");
    msg.setShort("short", (short) 1);
    msg.setString("string", "string");
    // Test with a 1Meg String
    StringBuffer bigSB = new StringBuffer(1024 * 1024);
    for (int i = 0; i < 1024 * 1024; i++) {
        bigSB.append('a' + i % 26);
    }
    String bigString = bigSB.toString();
    msg.setString("bigString", bigString);
    msg = (ActiveMQMapMessage) msg.copy();
    assertEquals(msg.getBoolean("boolean"), true);
    assertEquals(msg.getByte("byte"), (byte) 1);
    assertEquals(msg.getBytes("bytes").length, 1);
    assertEquals(msg.getChar("char"), 'a');
    assertEquals(msg.getDouble("double"), 1.5, 0);
    assertEquals(msg.getFloat("float"), 1.5f, 0);
    assertEquals(msg.getInt("int"), 1);
    assertEquals(msg.getLong("long"), 1);
    assertEquals(msg.getObject("object"), "stringObj");
    assertEquals(msg.getShort("short"), (short) 1);
    assertEquals(msg.getString("string"), "string");
    assertEquals(msg.getString("bigString"), bigString);
}

