 * +------+-------+-------+-------
 * |  T   |   T   |   F   |   U
 * |  F   |   F   |   F   |   F
 * |  U   |   U   |   F   |   U
 * +------+-------+-------+-------
 */
@Test
public void andEvaluation() throws Exception {
    assertSelectorEvaluatesToTrue("trueProp AND trueProp");
    assertSelectorEvaluatesToFalse("trueProp AND falseProp");
