/**
 * Tests that inflight message size goes up and comes back down to 0 after
 * messages are consumed
 *
 * @throws jakarta.jms.JMSException
 * @throws InterruptedException
 */
@Test(timeout = 60000)
public void testInflightMessageSize() throws Exception {
    Assume.assumeTrue(useTopicSubscriptionInflightStats);
    final long size = sendMessages(10);
    assertTrue("Inflight message size should be greater than the content length sent", Wait.waitFor(() -> getSubscription().getInFlightMessageSize() > size, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight sub dispatched message count should equal number of messages sent", Wait.waitFor(() -> getSubscription().getDispatchedQueueSize() == 10, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Destination inflight message count should equal number of messages sent", Wait.waitFor(() -> amqDestination.getDestinationStatistics().getInflight().getCount() == 10, WAIT_DURATION, SLEEP_DURATION));
    receiveMessages(10);
    assertTrue("Destination inflight message count should be 0", Wait.waitFor(() -> amqDestination.getDestinationStatistics().getInflight().getCount() == 0, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight sub dispatched message count should be 0", Wait.waitFor(() -> getSubscription().getDispatchedQueueSize() == 0, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight message size should be 0", Wait.waitFor(() -> getSubscription().getInFlightMessageSize() == 0, WAIT_DURATION, SLEEP_DURATION));
}

/**
 * Test that the in flight message size won't rise after prefetch is filled
 *
 * @throws Exception
 */
@Test(timeout = 60000)
public void testInflightMessageSizePrefetchFilled() throws Exception {
    Assume.assumeTrue(useTopicSubscriptionInflightStats);
    final long size = sendMessages(prefetch);
    assertTrue("Inflight message size should be greater than content length", Wait.waitFor(() -> getSubscription().getInFlightMessageSize() > size, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight sub dispatched message count should equal number of messages sent", Wait.waitFor(() -> getSubscription().getDispatchedQueueSize() == prefetch, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Destination inflight message count should equal number of messages sent", Wait.waitFor(() -> amqDestination.getDestinationStatistics().getInflight().getCount() == prefetch, WAIT_DURATION, SLEEP_DURATION));
    final long inFlightSize = getSubscription().getInFlightMessageSize();
    sendMessages(10);
    //Prefetch has been filled, so the size should not change with 10 more messages
    assertTrue("Destination inflight message count should equal number of messages sent", Wait.waitFor(() -> amqDestination.getDestinationStatistics().getInflight().getCount() == prefetch, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight sub dispatched message count should equal number of messages sent", Wait.waitFor(() -> getSubscription().getDispatchedQueueSize() == prefetch, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight message size should not change", Wait.waitFor(() -> getSubscription().getInFlightMessageSize() == inFlightSize, WAIT_DURATION, SLEEP_DURATION));
    receiveMessages(prefetch + 10);
    assertTrue("Destination inflight message count should be 0", Wait.waitFor(() -> amqDestination.getDestinationStatistics().getInflight().getCount() == 0, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight sub dispatched message count should be 0", Wait.waitFor(() -> getSubscription().getDispatchedQueueSize() == 0, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight message size should be 0", Wait.waitFor(() -> getSubscription().getInFlightMessageSize() == 0, WAIT_DURATION, SLEEP_DURATION));
}

/**
 * Test that the in flight message size will still rise if prefetch is not filled
 *
 * @throws Exception
 */
@Test(timeout = 60000)
public void testInflightMessageSizePrefetchNotFilled() throws Exception {
    Assume.assumeTrue(useTopicSubscriptionInflightStats);
    final long size = sendMessages(prefetch - 10);
    assertTrue("Inflight message size should be greater than content length", Wait.waitFor(() -> getSubscription().getInFlightMessageSize() > size, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight sub dispatched message count should equal number of messages sent", Wait.waitFor(() -> getSubscription().getDispatchedQueueSize() == prefetch - 10, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Destination inflight message count should equal number of messages sent", Wait.waitFor(() -> amqDestination.getDestinationStatistics().getInflight().getCount() == prefetch - 10, WAIT_DURATION, SLEEP_DURATION));
    //capture the inflight size and send 10 more messages
    final long inFlightSize = getSubscription().getInFlightMessageSize();
    sendMessages(10);
    //Prefetch has NOT been filled, so the size should rise with 10 more messages
    assertTrue("Inflight message size should be greater than previous inlight size", Wait.waitFor(() -> getSubscription().getInFlightMessageSize() > inFlightSize, WAIT_DURATION, SLEEP_DURATION));
    receiveMessages(prefetch);
    assertTrue("Destination inflight message count should be 0", Wait.waitFor(() -> amqDestination.getDestinationStatistics().getInflight().getCount() == 0, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight sub dispatched message count should be 0", Wait.waitFor(() -> getSubscription().getDispatchedQueueSize() == 0, WAIT_DURATION, SLEEP_DURATION));
    assertTrue("Inflight message size should be 0", Wait.waitFor(() -> getSubscription().getInFlightMessageSize() == 0, WAIT_DURATION, SLEEP_DURATION));
}

