    long inFlightSize = getSubscription().getInFlightMessageSize();
    for (int i = 0; i < 10; i++) {
        consumer.receive();
    }
    session.rollback();
    assertTrue("Destination inflight message count should not change on rollback", Wait.waitFor(() -> amqDestination.getDestinationStatistics().getInflight().getCount() == 10, WAIT_DURATION, SLEEP_DURATION));
