@Test
public void testNoDeadlockOnXaPoolExhaustion() throws Exception {
    final CountDownLatch done = new CountDownLatch(1);
    final CountDownLatch doneCommit = new CountDownLatch(1000);
    final ActiveMQXAConnectionFactory factory = new ActiveMQXAConnectionFactory(broker.getTransportConnectorByScheme("tcp").getPublishableConnectString());
    ExecutorService executorService = Executors.newCachedThreadPool();
    // some contention over pool of 2
    for (int i = 0; i < 3; i++) {
        executorService.execute(new Runnable() {

            @Override
            public void run() {
                try {
                    ActiveMQXAConnection conn = (ActiveMQXAConnection) factory.createXAConnection();
                    conn.start();
                    XASession sess = conn.createXASession();
                    while (done.getCount() > 0 && doneCommit.getCount() > 0) {
                        Xid xid = createXid();
                        sess.getXAResource().start(xid, XAResource.TMNOFLAGS);
                        MessageProducer producer = sess.createProducer(sess.createQueue("test"));
                        producer.send(sess.createTextMessage("test"));
                        sess.getXAResource().end(xid, XAResource.TMSUCCESS);
                        sess.getXAResource().prepare(xid);
                        sess.getXAResource().commit(xid, false);
                        doneCommit.countDown();
                    }
                    conn.close();
                } catch (Exception ignored) {
                    ignored.printStackTrace();
                }
            }
        });
    }
    executorService.execute(new Runnable() {

        @Override
        public void run() {
            try {
                while (!done.await(10, TimeUnit.MILLISECONDS) && doneCommit.getCount() > 0) {
                    jdbcPersistenceAdapter.cleanup();
                }
            } catch (Exception ignored) {
            }
        }
    });
    executorService.shutdown();
    boolean allComplete = executorService.awaitTermination(40, TimeUnit.SECONDS);
    if (!allComplete) {
        TestSupport.dumpAllThreads("Why-at-count-" + doneCommit.getCount() + "-");
    }
    done.countDown();
    assertTrue("all complete", allComplete);
    executorService.shutdownNow();
    assertTrue("xa tx done", doneCommit.await(10, TimeUnit.SECONDS));
}

@Test
public void testConcurrentDlqOk() throws Exception {
    final Destination dest = new ActiveMQQueue("DD");
    final ActiveMQConnectionFactory amq = new ActiveMQConnectionFactory(broker.getTransportConnectorByScheme("tcp").getPublishableConnectString());
    amq.setWatchTopicAdvisories(false);
    broker.setIoExceptionHandler(new DefaultIOExceptionHandler() {

        @Override
        public void handle(IOException exception) {
            LOG.error("handle IOException from store", exception);
            gotError.set(true);
        }
    });
    final var loggerRB = org.apache.logging.log4j.core.Logger.class.cast(LogManager.getLogger(RegionBroker.class));
    final var loggerJDBC = org.apache.logging.log4j.core.Logger.class.cast(LogManager.getLogger(JDBCPersistenceAdapter.class));
    loggerRB.get().addAppender(appender, Level.DEBUG, new AbstractFilter() {
    });
    loggerRB.addAppender(appender);
    loggerJDBC.get().addAppender(appender, Level.DEBUG, new AbstractFilter() {
    });
    loggerJDBC.addAppender(appender);
    final int numMessages = 100;
    final AtomicInteger consumed = new AtomicInteger(numMessages);
    produceMessages(amq, dest, numMessages);
    ExecutorService executorService = Executors.newCachedThreadPool();
    for (int i = 0; i < 50; i++) {
        executorService.execute(new Runnable() {

            @Override
            public void run() {
                Connection connection = null;
                Session session = null;
                MessageConsumer consumer = null;
                try {
                    connection = amq.createConnection();
                    connection.setExceptionListener(new jakarta.jms.ExceptionListener() {

                        public void onException(jakarta.jms.JMSException e) {
                            e.printStackTrace();
                        }
                    });
                    //set custom redelivery policy with 0 retries to force move to DLQ
                    RedeliveryPolicy queuePolicy = new RedeliveryPolicy();
                    queuePolicy.setMaximumRedeliveries(0);
                    ((ActiveMQConnection) connection).setRedeliveryPolicy(queuePolicy);
                    connection.start();
                    session = connection.createSession(true, Session.SESSION_TRANSACTED);
                    consumer = session.createConsumer(dest);
                    while (consumed.get() > 0 && !gotError.get()) {
                        Message message = consumer.receive(4000);
                        if (message != null) {
                            consumed.decrementAndGet();
                            session.rollback();
                        }
                    }
                } catch (Exception e) {
                    LOG.error("Error on consumption", e);
                    gotError.set(true);
                } finally {
                    try {
                        if (connection != null) {
                            connection.close();
                        }
                    } catch (Exception ignored) {
                    }
                }
            }
        });
    }
    executorService.shutdown();
    boolean allComplete = executorService.awaitTermination(60, TimeUnit.SECONDS);
    executorService.shutdownNow();
    LOG.info("Total messages: " + broker.getAdminView().getTotalMessageCount());
    LOG.info("Total enqueues: " + broker.getAdminView().getTotalEnqueueCount());
    LOG.info("Total deueues: " + broker.getAdminView().getTotalDequeueCount());
    assertTrue(allComplete);
    assertEquals("all consumed", 0l, consumed.get());
    assertEquals("all messages get to the dlq", numMessages * 2, broker.getAdminView().getTotalEnqueueCount());
    assertEquals("all messages acked", numMessages, broker.getAdminView().getTotalDequeueCount());
    assertFalse("no error", gotError.get());
}

@Test
public void testShutdownWithoutTransportRestart() throws Exception {
    Mockery context = new Mockery() {

        {
            setImposteriser(ClassImposteriser.INSTANCE);
        }
    };
    Thread.setDefaultUncaughtExceptionHandler(new Thread.UncaughtExceptionHandler() {

        @Override
        public void uncaughtException(Thread t, Throwable e) {
            LOG.error("unexpected exception {} on thread {}", e, t);
            exceptions.put(t, e);
        }
    });
    final BrokerService brokerService = context.mock(BrokerService.class);
    final JDBCPersistenceAdapter jdbcPersistenceAdapter = context.mock(JDBCPersistenceAdapter.class);
    final Locker locker = context.mock(Locker.class);
    final States jdbcConn = context.states("jdbc").startsAs("down");
    final States broker = context.states("broker").startsAs("started");
    // simulate jdbc up between hasLock and checkpoint, so hasLock fails to verify
    context.checking(new Expectations() {

        {
            allowing(brokerService).isStarted();
            will(returnValue(true));
            allowing(brokerService).isRestartAllowed();
            will(returnValue(false));
            allowing(brokerService).setSystemExitOnShutdown(with(false));
            allowing(brokerService).stopAllConnectors(with(any(ServiceStopper.class)));
            allowing(brokerService).getPersistenceAdapter();
            will(returnValue(jdbcPersistenceAdapter));
            allowing(jdbcPersistenceAdapter).allowIOResumption();
            allowing(jdbcPersistenceAdapter).getLocker();
            will(returnValue(locker));
            allowing(locker).keepAlive();
            when(jdbcConn.is("down"));
            will(returnValue(true));
            allowing(locker).keepAlive();
            when(jdbcConn.is("up"));
            will(returnValue(false));
            allowing(jdbcPersistenceAdapter).checkpoint(with(true));
            then(jdbcConn.is("up"));
            allowing(brokerService).stop();
            then(broker.is("stopped"));
        }
    });
    LeaseLockerIOExceptionHandler underTest = new LeaseLockerIOExceptionHandler();
    underTest.setBrokerService(brokerService);
    try {
        underTest.handle(new IOException());
        fail("except suppress reply ex");
    } catch (SuppressReplyException expected) {
    }
    assertTrue("broker stopped state triggered", Wait.waitFor(new Wait.Condition() {

        @Override
        public boolean isSatisified() throws Exception {
            LOG.info("broker state {}", broker);
            return broker.is("stopped").isActive();
        }
    }));
    context.assertIsSatisfied();
    assertTrue("no exceptions: " + exceptions, exceptions.isEmpty());
}

@Test
public void testStartWithDatabaseDown() throws Exception {
    final AtomicBoolean connectorStarted = new AtomicBoolean(false);
    final AtomicBoolean connectorStopped = new AtomicBoolean(false);
    // start new
    final var rootLogger = org.apache.logging.log4j.core.Logger.class.cast(LogManager.getRootLogger());
    final var appender = new AbstractAppender("testAppender", new AbstractFilter() {
    }, new MessageLayout(), false, new Property[0]) {

        @Override
        public void append(LogEvent event) {
            if (event.getMessage().getFormattedMessage().startsWith("JMX consoles can connect to")) {
                connectorStarted.set(true);
            }
            if (event.getMessage().getFormattedMessage().equals("Stopping jmx connector")) {
                connectorStopped.set(true);
            }
        }
    };
    appender.start();
    Level previousLevel = rootLogger.getLevel();
    rootLogger.get().addAppender(appender, Level.DEBUG, new AbstractFilter() {
    });
    rootLogger.addAppender(appender);
    rootLogger.setLevel(Level.DEBUG);
    // end new
    BrokerService broker = new BrokerService();
    broker.getManagementContext().setCreateConnector(true);
    broker.getManagementContext().setCreateMBeanServer(true);
    JDBCPersistenceAdapter jdbc = new JDBCPersistenceAdapter();
    EmbeddedDataSource embeddedDataSource = (EmbeddedDataSource) jdbc.getDataSource();
    // create a wrapper to EmbeddedDataSource to allow the connection be
    // reestablished to derby db
    dataSource = new ReconnectingEmbeddedDataSource(new SyncCreateDataSource(embeddedDataSource));
    dataSource.stopDB();
    jdbc.setDataSource(dataSource);
    jdbc.setLockKeepAlivePeriod(1000l);
    LeaseDatabaseLocker leaseDatabaseLocker = new LeaseDatabaseLocker();
    leaseDatabaseLocker.setHandleStartException(true);
    leaseDatabaseLocker.setLockAcquireSleepInterval(2000l);
    jdbc.setLocker(leaseDatabaseLocker);
    broker.setPersistenceAdapter(jdbc);
    LeaseLockerIOExceptionHandler ioExceptionHandler = new LeaseLockerIOExceptionHandler();
    ioExceptionHandler.setResumeCheckSleepPeriod(1000l);
    ioExceptionHandler.setStopStartConnectors(true);
    broker.setIoExceptionHandler(ioExceptionHandler);
    try {
        broker.start();
        fail("Broker should have been stopped!");
    } catch (Exception e) {
        Thread.sleep(5000);
        assertTrue("Broker should have been stopped!", broker.isStopped());
        Thread[] threads = ThreadExplorer.listThreads();
        for (int i = 0; i < threads.length; i++) {
            if (threads[i].getName().startsWith("IOExceptionHandler")) {
                fail("IOExceptionHanlder still active");
            }
        }
        if (connectorStarted.get() && !connectorStopped.get()) {
            fail("JMX Server Connector should have been stopped!");
        }
    } finally {
        dataSource = null;
        broker = null;
        rootLogger.removeAppender(appender);
        rootLogger.setLevel(previousLevel);
    }
}

