@Test(timeout = 60 * 1000)
public void testBrowseExpireActiveSub() throws Exception {
    final int numberOfMessages = 10;
    broker.setEnableMessageExpirationOnActiveDurableSubs(enableExpiration);
    // create durable subscription
    Connection con = createConnection("consumer");
    Session session = con.createSession(false, Session.AUTO_ACKNOWLEDGE);
    session.createDurableSubscriber(topic, "SubsId");
    long timeStamp = System.currentTimeMillis();
    sendMessages(numberOfMessages, timeStamp);
    ObjectName[] subs = broker.getAdminView().getDurableTopicSubscribers();
    assertEquals(1, subs.length);
    ObjectName subName = subs[0];
    DurableSubscriptionViewMBean sub = (DurableSubscriptionViewMBean) broker.getManagementContext().newProxyInstance(subName, DurableSubscriptionViewMBean.class, true);
    assertEquals(true, sub.isActive());
    // browse the durable sub
    CompositeData[] data = sub.browse();
    assertNotNull(data);
    assertEquals(numberOfMessages, data.length);
    Destination dest = broker.getDestination(topic);
    assertEquals(0, dest.getDestinationStatistics().getExpired().getCount());
    // add every 3rd message to the expiration list
    TopicMessageStore topicStore = (TopicMessageStore) dest.getMessageStore();
    LinkedList<org.apache.activemq.command.Message> messagesToExpire = new LinkedList<>();
    topicStore.recover(new MessageRecoveryListener() {

        @Override
        public boolean recoverMessage(org.apache.activemq.command.Message message) throws Exception {
            int index = (int) message.getProperty("index");
            if (index % 3 == 0)
                messagesToExpire.add(message);
            return true;
        }

        @Override
        public boolean recoverMessageReference(MessageId messageReference) throws Exception {
            return true;
        }

        @Override
        public boolean hasSpace() {
            return true;
        }

        @Override
        public boolean isDuplicate(MessageId id) {
            return false;
        }
    });
    // expire messages in the topic store
    for (org.apache.activemq.command.Message message : messagesToExpire) {
        message.setExpiration(timeStamp - 1);
        topicStore.updateMessage(message);
    }
    // browse (should | should not) expire the messages on the destination if expiration is (enabled | not enabled)
    data = sub.browse();
    assertNotNull(data);
    assertEquals(enableExpiration ? messagesToExpire.size() : 0, dest.getDestinationStatistics().getExpired().getCount());
    session.close();
    con.close();
}

@Test
public void testAdvisoryTopic() throws Exception {
    Connection connection = createConnection();
    Session session = connection.createSession(false, Session.AUTO_ACKNOWLEDGE);
    ActiveMQDestination queue = (ActiveMQDestination) session.createQueue("AdvisoryTopicCleanUpTestQueue");
    MessageProducer prod = session.createProducer(queue);
    Message message = session.createMessage();
    prod.send(message);
    message = session.createMessage();
    prod.send(message);
    message = session.createMessage();
    prod.send(message, Message.DEFAULT_DELIVERY_MODE, Message.DEFAULT_PRIORITY, 1000);
    connection.close();
    connection = createConnection();
    session = connection.createSession(false, Session.CLIENT_ACKNOWLEDGE);
    MessageConsumer consumer = session.createConsumer(queue);
    message = consumer.receive(60 * 1000);
    message.acknowledge();
    connection.close();
    connection = null;
    for (int i = 0; i < 2; i++) {
        connection = createConnection();
        session = connection.createSession(true, Session.CLIENT_ACKNOWLEDGE);
        consumer = session.createConsumer(queue);
        message = consumer.receive(60 * 1000);
        session.rollback();
        connection.close();
        connection = null;
    }
    Thread.sleep(2 * 1000);
    connection = createConnection();
    session = connection.createSession(false, Session.CLIENT_ACKNOWLEDGE);
    consumer = session.createConsumer(queue);
    message = consumer.receive(1000);
    if (message != null)
        message.acknowledge();
    connection.close();
    connection = null;
    TimeUnit.SECONDS.sleep(1);
    ActiveMQDestination[] dests = broker.getRegionBroker().getDestinations();
    for (ActiveMQDestination destination : dests) {
        String name = destination.getPhysicalName();
        if (name.contains(queue.getPhysicalName())) {
            LOG.info("Destination on Broker before removing the Queue: " + name);
        }
    }
    dests = broker.getRegionBroker().getDestinations();
    if (dests == null) {
        fail("Should have Destination for: " + queue.getPhysicalName());
    }
    broker.getAdminView().removeQueue(queue.getPhysicalName());
    dests = broker.getRegionBroker().getDestinations();
    if (dests != null) {
        for (ActiveMQDestination destination : dests) {
            String name = destination.getPhysicalName();
            LOG.info("Destination on broker after removing the Queue: " + name);
            assertFalse("Advisory topic should not exist. " + name, name.startsWith("ActiveMQ.Advisory") && name.contains(queue.getPhysicalName()));
        }
    }
}

