            houseKeeper.start();
        if (BROKER_RESTART <= 0)
            Thread.sleep(RUNTIME);
        else {
            long end = System.currentTimeMillis() + RUNTIME;
            while (true) {
                long now = System.currentTimeMillis();
                if (now > end)
                    break;
                now = end - now;
                now = now < BROKER_RESTART ? now : BROKER_RESTART;
                Thread.sleep(now);
                restartBroker();
            }
        }
    } catch (Throwable e) {
