/**
 * Before AMQ-5896 there was the possibility of an InstanceNotFoundException when
 * brokerFacade.getQueue if a destination was deleted after the initial list was looked
 * up but before iterating over the list to find the right destination by name.
 */
@Test(timeout = 10000)
public void testGetDestinationRaceCondition() throws Exception {
    final CountDownLatch getQueuesLatch = new CountDownLatch(1);
    final CountDownLatch destDeletionLatch = new CountDownLatch(1);
    // Adding a pause so we can test the case where the destination is
    // deleted in between calling getQueues() and iterating over the list
    //and calling getName() on the DestinationViewMBean
    // See AMQ-5896
    RemoteJMXBrokerFacade brokerFacade = new RemoteJMXBrokerFacade() {

        @Override
        protected DestinationViewMBean getDestinationByName(Collection<? extends DestinationViewMBean> collection, String name) {
            try {
                //we are done getting the queue collection so let thread know
                //to remove destination
                getQueuesLatch.countDown();
                //wait until other thread is done removing destination
                destDeletionLatch.await();
            } catch (InterruptedException e) {
            }
            return super.getDestinationByName(collection, name);
        }
    };
    SystemPropertiesConfiguration configuration = new SystemPropertiesConfiguration();
    brokerFacade.setConfiguration(configuration);
    //Create the destination
    final ActiveMQQueue queue = new ActiveMQQueue("queue.test");
    brokerService.getDestination(queue);
    //after 1 second delete
    ExecutorService service = Executors.newCachedThreadPool();
    service.submit(new Runnable() {

        @Override
        public void run() {
            try {
                //wait for confirmation that the queue list was obtained
                getQueuesLatch.await();
                brokerService.removeDestination(queue);
                //let original thread know destination was deleted
                destDeletionLatch.countDown();
            } catch (Exception e) {
            }
        }
    });
    //Assert that the destination is now null because it was deleted in another thread
    //during iteration
    assertNull(brokerFacade.getQueue(queue.getPhysicalName()));
    service.shutdown();
}

@Test(timeout = 15 * 1000)
public void testAjaxClientReceivesMessagesWhichAreSentToQueueWhileClientIsPolling() throws Exception {
    LOG.debug("*** testAjaxClientReceivesMessagesWhichAreSentToQueueWhileClientIsPolling ***");
    int port = getPort();
    HttpClient httpClient = new HttpClient();
    httpClient.start();
    // client 1 subscribes to a queue
    LOG.debug("SENDING LISTEN");
    String sessionId = subscribe(httpClient, port, "destination=queue://test&type=listen&message=handler");
    // client 1 polls for messages
    LOG.debug("SENDING POLL");
    final StringBuffer buf = new StringBuffer();
    final CountDownLatch latch = asyncRequest(httpClient, "http://localhost:" + port + "/amq?timeout=5000", buf, sessionId);
    // while client 1 is polling, client 2 sends messages to the queue
    LOG.debug("SENDING MESSAGES");
    sendMessages(httpClient, port, ("destination=queue://test&type=send&message=msg1&" + "d1=queue://test&t1=send&m1=msg2&" + "d2=queue://test&t2=send&m2=msg3").getBytes());
    LOG.debug("DONE POSTING MESSAGES");
    // wait for poll to finish
    latch.await();
    String response = buf.toString();
    // messages might not all be delivered during the 1st poll.  We need to check again.
    final StringBuffer buf2 = new StringBuffer();
    final CountDownLatch latch2 = asyncRequest(httpClient, "http://localhost:" + port + "/amq?timeout=5000", buf2, sessionId);
    latch2.await();
    String fullResponse = response + buf2.toString();
    LOG.debug("full response : " + fullResponse);
    assertContains("<response id='handler' destination='queue://test' >msg1</response>", fullResponse);
    assertContains("<response id='handler' destination='queue://test' >msg2</response>", fullResponse);
    assertContains("<response id='handler' destination='queue://test' >msg3</response>", fullResponse);
    assertResponseCount(3, fullResponse);
    httpClient.stop();
}

